Lemma INSTX : SPTX.instx L HI mw LBo (g_lbv eg) cr sp r P V E S2 B (kx + PMX.kenc L eg) bx g ps R M model SCRC G.HDECL Pb Vb Eb line0 pos0 XV SPT.noeb.
Proof.
  unfold SPTX.instx. split; [|split; [exact OBJS | reflexivity]].
  unfold SPT.inst. destruct Hlpr as (Q1 & Q2). pose proof WFM as (F1 & F2 & F3 & F4 & _).
  pose proof Hentry as (_ & _ & Hsp & _ & Hstk). pose proof (L5C.stk_floor _ _ _ _ Hstk) as FL. pose proof (L5C.stk_window _ _ _ _ Hstk) as (SW1 & SW2 & SW3).
  pose proof OP as (OP1 & OP2 & OP3). pose proof OV as (OV1 & OV2 & OV3). pose proof OE as (OE1 & OE2 & OE3).
  assert (HSC : 0 <= SCRC <= 2 ^ 20) by (split; apply Z.leb_le; vm_compute; reflexivity).
  split; [exact HIok|]. split; [exact LAY|]. split; [exact HH|]. split; [exact Hentry|].
  split; [rewrite SCRV; split; apply Z.leb_le; vm_compute; reflexivity|]. split; [apply Z.leb_le; vm_compute; reflexivity|].
  split; [rewrite ps_mw; exact HPA|]. split; [exact (PML.wf_ps_stale_of ps HWF)|]. split; [unfold level in *; lia|].
  split.
  { destruct HBB as (HB1 & HB2). pose proof (SPT.win_le M P ps HPA) as HWL. unfold PML.winlen, PML.buf_need in HB1.
    destruct (Z.eqb_spec (PML.ps_st ps) PML.ST_STRING) as [Q|_]; [contradiction|]. rewrite Bool.andb_false_r in HB1. destruct (PML.ps_win ps) as [[p e]|]; lia. }
  split; [unfold PML.handled in F3; lia|].
  split; [exact HVIS|]. split; [exact HEC|]. split; [exact HLS|]. split; [exact HPC|].
  split; [exact OP|]. split; [exact OV|]. split; [exact OE|]. split; [exact AP1|]. split; [exact AP2|]. split; [exact AP3|].
  split; [exact Hline0|]. split; [exact Hpos0|]. split; [exact Q1|]. split; [exact Q2|].
  split; [unfold PB.uv, Pb; cbn [edenot]; rewrite (SPT.EV0 mw B ps R line0 pos0 XV SPT.noeb 10%bv), Ha0; apply u64_of_Z; lia|].
  split; [unfold PB.uv, Vb; cbn [edenot]; rewrite (SPT.EV0 mw B ps R line0 pos0 XV SPT.noeb 11%bv), Ha1; apply u64_of_Z; lia|].
  split; [unfold PB.uv, Eb; cbn [edenot]; rewrite (SPT.EV0 mw B ps R line0 pos0 XV SPT.noeb 12%bv), Ha2; apply u64_of_Z; lia|].
  split; [reflexivity|]. split; reflexivity.
Qed.
