  PPS.bufcred L cr1 bcap (PPS.stk_kx L (scap_of i E1) + (kx + PMES.kenc L g1)) (PPS.stk_bx L (scap_of i E1) + (bxu + PMES.benc L g1)).
Lemma CRED_BLK : forall g1 i j E1 E2 cr1, CH2.den E2 (nth j G.BLS []) = CH2.den E1 (nth i G.BLS []) -> CredV g1 i E1 cr1 -> CredV g1 j E2 cr1.
  intros g1 i j E1 E2 cr1 Hd H. unfold CredV, scap_of in *. rewrite Hd. exact H.
Qed.
Lemma cred_pc : forall g1 i E1 cr1 ps1, CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps1 -> PML.ps_bcap ps1 = bcap -> In (PML.ps_scap ps1) [66; 132; 264; 528; 1056] ->
  (CredV g1 i E1 cr1 <-> PML.pcredit_x L cr1 ps1 (kx + PMX.kenc L g1) (bxu + PMES.benc L g1)).
  intros g1 i E1 cr1 ps1 Hd Hb Hs. unfold CredV, scap_of. rewrite Hd. unfold PML.ps_blocks. cbn [nth snd]. rewrite <- Hb.
  pose proof (KENC0 g1) as K1. pose proof (EK.benc_nonneg L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) g1) as B1.
  symmetry. exact (PPS.pcredit_x_bufcred L cr1 ps1 (kx + PMX.kenc L g1) (bxu + PMES.benc L g1) (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) Hs ltac:(lia) ltac:(lia)).
Qed.
