Lemma exit_gen : forall g1 M0c, OKV M0c -> forall i c k ps1 pc lvl stv morev sbv sendv scendv,
  is_leaf i c k ps1 (CC.TOther pc) -> PB.exit_base_chk GT.NF RETPC c ps1 = true -> view_chk (SR.ps_cells ps1) lvl stv morev sbv sendv scendv = true ->
  (forall E1 E' R' (M1 M' : mem) model1, env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> XIv g1 i E1 M1 -> HAMBV g1 M0c i E1 M' model1 -> env_agree GT.NF E0 E' ->
      L5.defined M' E 16 ->
      exists (more' : bool) (stack' : list Z) (scap' code : Z) (g' : PML.ls_state),
        uv E' morev = PML.b2z more' /\ L5.bytes_at RSEGS M' (uv E' sbv) stack' /\ uv E' sendv = uv E' sbv + Z.of_nat (length stack') /\ uv E' scendv = uv E' sbv + scap' /\
        Z.of_nat (length stack') <= scap' /\ In scap' [66; 132; 264; 528; 1056] /\
        PML.ec_at M' E code /\ (code <> 0 -> more' = false) /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\ ((code = 0 <-> i = JVIS) /\ (code = 0 -> 0 <= level + DLVL)) /\
        CH2.den E1 (nth i G.BLS []) = [(bptr, bcap); (uv E' sbv, scap')] /\
        forall buf, let ps' := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) (uv E' lvl) stack' (uv E' sbv) scap' bcap bptr buf (PML.ps_win ps) in
          PML.wf_ps ps' /\ PML.buf_need ps' = 0 /\
          ((code = 0 /\ PML.ps_level ps' = PML.ps_level ps + 1 /\ PML.ps_st ps' = STNEW /\ PML.ps_more ps' = true /\ PML.ps_stack ps' = PML.ps_stack ps ++ [KIND] /\ PML.ps_win ps' = PML.ps_win ps)
           \/ (code = 5 /\ PML.ps_level ps = 1024))) ->
  CC.leaf_ok (hl_segs L) G.CPS (AMB3XV g1 M0c) K PML.fp_ok i c ps1.
Proof.
  intros g1 M0c OKV0 i c k ps1 pc lvl stv morev sbv sendv scendv IL Hbase HV HKIND.
  intros fx' E1 R1 M1 model1 E' R' M' HAt [HAmb HX] HFP Hag HLF _.
  pose proof Hentry as (Hra & Hraok & _).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (kitx SPTX.okV_defc M0c OKV0) as DEFC.
  assert (Hc : nth_error G.CPS i = Some c) by (destruct IL as (tags & Hc & _); exact Hc).
  pose proof (gblocks_amb g1 M0c i E1 M1 model1 HAmb) as HGB.
  apply (PB.exit_ret L HI HIok LAY GT.NF E0 M0c model (LBr g1) sp G.HDECL W G.BLS (CredV g1) STKF SCRP NF32 U2 W_OK WRS_OK G.CPS G.TAGS K (XIv g1)
           (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV0) (fun _ => 0) (fun _ => 0)
           SCRC (proj2 S7) S6 DEFC R (SPT.EV0 mw B ps R line0 pos0 XV SPT.noeb) r Hra Hraok heap_ok3 RETPC i c k ps1 pc ret_at IL Hbase fx' E1 R1 M1 model1 E' R' M' HAt HAmb Hag HLF).
  intros HRP HP HA' HagE'.
  pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HK.
  pose proof OP as (OP1 & OP2 & OP3). pose proof OE as (OE1 & OE2 & OE3).
  pose proof (SPT.pa_def _ _ _ HPA) as HdefP. pose proof HEC as (_ & HEd & _).
  assert (HdP' : L5.defined M' P 272) by (apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' model1 P 272 HA' OKV0 HdefP); left; lia).
  assert (HdE' : L5.defined M' E 16) by (apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' model1 E 16 HA' OKV0 HEd); left; lia).
  destruct (HKIND E1 E' R' M1 M' model1 Hag HLF HX HA' HagE' HdE')
    as (more' & stack' & scap' & code & g' & Hmo' & Hby' & Hse & Hsc & Hle & Hin' & Hec' & Hcm & Hls' & Hg' & (Hcv & Hlvl) & Hden & HPS).
  unfold view_chk in HV. destruct (SPA.pview_w (SR.ps_cells ps1) Pb PE CE) as [pv|] eqn:HPV; [|discriminate].
  apply andb_prop in HV as [HV Y12]. apply andb_prop in HV as [HV Y11]. apply andb_prop in HV as [HV Y10]. apply andb_prop in HV as [HV Y9]. apply andb_prop in HV as [HV Y8].
  apply andb_prop in HV as [HV Y7]. apply andb_prop in HV as [HV Y6]. apply andb_prop in HV as [HV Y5]. apply andb_prop in HV as [HV Y4]. apply andb_prop in HV as [HV Y3].
  apply andb_prop in HV as [Y1 Y2]. apply expr_eqb_eq in Y1, Y2, Y3, Y4, Y5, Y6, Y7, Y8, Y9, Y10, Y11, Y12.
  destruct (FRZ E' HagE') as (G2 & GP' & GE & GV & G41 & G42 & G43 & G44 & G45 & G46 & G36 & G38 & G39 & G40 & GSE & GSC & GPE & GCE & G32 & G33 & _).
  destruct (SPA.parser_view_w E' M' (SR.ps_cells ps1) Pb PE CE pv P more' (PML.ps_done ps) stack' scap' mw HK HPV GP' ltac:(lia) ltac:(lia)) as (buf & HPA' & Hlen & _).
  - rewrite Y7. exact Hmo'.
  - rewrite Y8, G46. reflexivity.
  - rewrite Y10. exact Hby'.
  - rewrite Y11, Y10. exact Hse.
  - rewrite Y12, Y10. exact Hsc.
  - exact Hle.
  - rewrite Y3. exact G32.
  - rewrite Y2. exact G33.
  - exact (kit SPT.mw_le).
  - exact HdP'.
  - rewrite Y4, Y5, Y6, Y1, Y10, G43, G44, GCE, GPE in HPA'. rewrite Y9, G36 in Hlen.
    set (ps' := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) (uv E' lvl) stack' (uv E' sbv) scap' bcap bptr buf (PML.ps_win ps)) in *.
    destruct (HPS buf) as (Hwf' & Hneed' & HREL). fold ps' in Hwf', Hneed', HREL.
    assert (Hden' : CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps') by (rewrite Hden; reflexivity).
    pose proof HA' as (Hmo1 & Hbv1 & HagE1 & (cr1 & HH1 & HC1) & _ & _).
    pose proof HX as (HXj & HXI & HGF).
    pose proof (xinv_leaf g1 i c E1 M1 M' E' R' ps1 Hc HGB HX HagE' HLF) as (HINV2 & HLIT2).
    pose proof (kitx SPTX.okV_hpres g1 M0c M' OKV0 HP) as HP2.
    assert (HWB2 : PMW.win_bytes M' ps' ww).
    { apply (SPTW.win_bytes_kept L HI HIok LAY (PML.ps_blocks ps ++ LBo ++ gB eg) cr M M' (m_vmmaps model) LBo sp SCRC W ps ps' ww HH);
        [intros b0 Hb0; apply in_or_app; right; apply in_or_app; left; exact Hb0 | exact (proj1 HP2) | exact S6 | lia | lia
        | exact (SPTW.wparx_split L LAY sp P V E S2 OBJS) | exact HWIN | exact HWB | reflexivity]. }
    apply (Hcont fx' R' M' model1 (PML.ps_blocks ps' ++ LBo ++ gB g1) cr1 LBo W HFP);
      [| exact HRP | exact HP2 | exact Hbv1 | unfold CH2.cur, CH2V.LBr in HH1; rewrite Hden' in HH1; exact HH1].
    exists ps', code, g', g1.
    split; [exact HPA'|]. split; [exact Hwf'|].
    split; [apply (SPT.win_ok_tr M M' LBo ps ps' eq_refl HWIN); intros ch p n Hch C1 C2 Hwd;
            apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' model1 p n HA' OKV0 Hwd); right; exists ch; split; [exact Hch | lia]|].
    split; [apply (SPT.buf_bound_tr ps ps' B eq_refl); [unfold ps'; cbn [PML.ps_buf]; exact Hlen | rewrite Hneed', need0; lia | exact HBB]|].
    split; [exact Hec'|]. split; [exact Hcm|]. split; [exact Hls'|]. split; [exact Hg'|].
    split; [exact HINV2|]. split; [exact HLIT2|].
    split.
    { intros H0. pose proof (proj1 Hcv H0) as Hi. subst i.
      destruct HREL as [(_ & HL' & _)|(H5 & _)]; [|lia].
      apply (sync_exit g1 JVIS ps' HGF).
      - rewrite Nat.eqb_refl. exact (Hlvl H0).
      - rewrite Nat.eqb_refl, HL'. unfold DLVL, level. lia.
      - apply PMX.key_inv_pos. rewrite HL'. pose proof WFM as (_ & F2 & _). unfold level in F2. lia. }
    split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
    split; [exact (proj1 (cred_pc g1 i E1 cr1 ps' Hden' eq_refl Hin') HC1)|].
    split; [exact HREL|].
    apply (SPTW.w3_begin_container true cw M M' P ps ps' ww eg g1 code HRM Hwf' eq_refl HREL).
    + intros H0. pose proof (proj1 Hcv H0) as Hi. rewrite Hi in HGF. unfold GF in HGF. rewrite Nat.eqb_refl in HGF. exact HGF.
    + intros Hn. assert (Hi : Nat.eqb i JVIS = false) by (apply Nat.eqb_neq; intros Hi; apply Hn; exact (proj2 Hcv Hi)).
      unfold GF in HGF. rewrite Hi in HGF. exact HGF.
    + exact HWB2.
Qed.

