Lemma leaf_vis : forall g1 M0c, OKV M0c -> forall c k ps1 cj ci, is_leaf JPUSH c k ps1 (CC.TOther VIS) -> CH2.ret_of G.RETS JPUSH k = Some JVIS -> nth_error G.CPS JVIS = Some cj -> SR.ps_pc ps1 = VIS ->
  PB.has (SR.ps_cells ps1) (KRange (EVar 41) 0 1023) = true -> VBX.vis_chk GT.NF G.HDECL Vb c ps1 cj (nth JPUSH G.BLS []) (nth JVIS G.BLS []) = Some ci ->
  CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv G.CPS K PML.fp_ok g1 M0c JPUSH c ps1.
Proof.
  intros g1 M0c HOK c k ps1 cj ci IL Hret Hcj Hpc Hlv Hchk.
  assert (Hc : nth_error G.CPS JPUSH = Some c) by (destruct IL as (tags & Hc & _); exact Hc).
  assert (Hc' : c = nth JPUSH G.CPS G.cp0) by exact (eq_sym (nth_error_nth _ _ G.cp0 Hc)).
  assert (HNF : (GT.NF <= CC.cp_nx c)%nat) by (rewrite Hc'; vm_compute; lia).
  assert (Hvars : forallb (fun x => APC.expr_vars_lt (CC.cp_nx c) (fst x) && APC.expr_vars_lt (CC.cp_nx c) (snd x)) (nth JPUSH G.BLS []) = true) by (rewrite Hc'; vm_compute; reflexivity).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof OBJS as (OB1 & OB2 & OB3 & OB4 & OA1 & OA2 & OA3 & OA4 & OA5 & OA6).
  pose proof (kit SPT.NUM) as (BR1 & (B0 & B1 & B2 & B3 & B4) & BD1 & BD2 & A1 & Hk & N1 & N2 & N3 & N4 & N5 & _).
  eapply (VBXU.vis_leaf_okU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv) with (pc := VIS) (ev := EvBegin true) (Args := fun _ _ _ => True)
    (KXE := fun E1 => PPS.stk_kx L (scap_of JPUSH E1) + kx + Z.log2 (2 ^ 27 / bcap) * hl_k_per_malloc L)
    (BXE := fun E1 => PPS.stk_bx L (scap_of JPUSH E1) + bxu + ((2 ^ 28 - 2 * bcap) + Z.log2 (2 ^ 27 / bcap) * hl_b_overhead L)) (j := JVIS).
  all: first [exact STKF | exact SCRP | exact NF32 | exact U2 | exact TP0 | exact W_OK | exact CRS_OK | exact WRS_OK | exact IMG_OK | exact HKnil | exact DEF0 | exact W_ENC | exact S2LT | exact VBARR | exact HOK | exact IL | exact Hret | exact Hcj | exact Hpc | exact Hchk | reflexivity | idtac].
  - vm_compute. reflexivity.
  - destruct (FRZ E0 (CC.env_agree_refl _ _)) as (_ & _ & _ & GV & _). exact GV.
  - exact (kitx SPTX.FRZS2 E0 (CC.env_agree_refl _ _)).
  - exact (conj OB2 (conj OB3 OA4)).
  - intros E1 R1 M1 model1 E' R' M' cr1 HAt HA HX Hag HLF HCF HH1 HC1.
    pose proof (amb_agree g1 M0c JPUSH E1 M1 model1 HA) as Hag0.
    assert (HagE' : env_agree GT.NF E0 E') by (eapply CC.env_agree_trans; [exact Hag0 | eapply CC.env_agree_le; [exact Hag | exact HNF]]).
    pose proof (leaf_know c ps1 E' R' M1 M' HLF) as HK.
    destruct (FRZ E' HagE') as (G2 & GP' & GE & GV & G41 & _).
    assert (HL : level <= 1023) by (pose proof (PB.has_ok E' M' _ _ HK Hlv) as Q; cbn [kentry_ok] in Q; fold (uv E' (EVar 41)) in Q; rewrite G41 in Q; unfold level; lia).
    pose proof (gblocks_amb g1 M0c JPUSH E1 M1 model1 HA) as HGB.
    pose proof (xinv_leaf g1 JPUSH c E1 M1 M' E' R' ps1 Hc HGB HX HagE' HLF) as (HEI & HLT).
    destruct HX as (HXj & _ & HGF). rewrite xi_push in HXj. destruct HXj as (HS & b' & cap' & Hden & Hby & Hcin & Hcap & HBR).
    assert (HG1 : g1 = eg) by exact HGF. subst g1.
    assert (HLOW : forall a, 0 <= a < hl_ceil L -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) by (apply (below_frame JPUSH c E' M1 M' Hc HagE'); exact (CC.lf_frame _ _ _ _ _ _ _ HLF)).
    split; [exact I|]. split; [exact HEI|].
    split; [unfold ev_guard; destruct HSYNC as (HD & _); rewrite HD; unfold MAX_DEPTH, level in *; lia|].
    split; [exact (SPXWU.room_begin_container true cw M P ps ww eg HRM ltac:(unfold level in HL; lia) HROOM)|].
    split; [apply (EK.img_ro_agree M M'); [intros a Ha; assert (Hf : PB2.ls_foot a) by (unfold PB2.ls_foot; left; lia); rewrite (HLOW a (foot_low a Hf)); exact (HS a Hf) | exact (proj1 HLS)]|].
    split; [exact HLT|].
    unfold CredV, scap_of in HC1. rewrite Hden in HC1. cbn [nth snd] in HC1.
    unfold scap_of. rewrite Hden. cbn [nth snd].
    assert (SK : 0 <= PPS.stk_kx L cap') by (unfold PPS.stk_kx; apply Z.mul_nonneg_nonneg; [apply Z.log2_nonneg | exact (PmLayout.ly_kpm L LAY)]).
    assert (SB : 0 <= PPS.stk_bx L cap') by (unfold PPS.stk_bx; pose proof (Z.log2_nonneg (1056 / cap')); pose proof (PmLayout.ly_bov L LAY); cbn [In] in Hcin; nia).
    rewrite !Z.add_assoc in HC1.
    exact (SPXWU.ecredit_of_bufcredU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr1 bcap (PPS.stk_kx L cap' + kx) (PPS.stk_bx L cap' + bxu) eg HC1 ltac:(lia) ltac:(lia)).
  - intros E1 E' R' M1 M' E2 M2 g' cr' HX HagE' Hag HLF Hag2 Hnx HP Hspc1 Hspc2 HVR HEC'.
    destruct HVR as (HEI2 & HLT2 & Hes & pay & Hpay & Hlen).
    destruct HX as (HXj & _ & HGF). rewrite xi_push in HXj. destruct HXj as (HS & b' & cap' & Hden & Hby & Hcin & Hcap & HBR).
    assert (HG1 : g1 = eg) by exact HGF. subst g1.
    assert (HLOW : forall a, 0 <= a < hl_ceil L -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) by (apply (below_frame JPUSH c E' M1 M' Hc HagE'); exact (CC.lf_frame _ _ _ _ _ _ _ HLF)).
    assert (Hagg : env_agree (CC.cp_nx c) E1 E2) by (eapply CC.env_agree_trans; [exact Hag | eapply CC.env_agree_le; [exact Hag2 | exact Hnx]]).
    assert (HdenE' : CH2.den E' (nth JPUSH G.BLS []) = [(bptr, bcap); (b', cap')]) by (rewrite (CH2.den_agree _ E1 E' _ Hag Hvars); exact Hden).
    assert (HdenE2 : CH2.den E2 (nth JPUSH G.BLS []) = [(bptr, bcap); (b', cap')]) by (rewrite (CH2.den_agree _ E1 E2 _ Hagg Hvars); exact Hden).
    pose proof HBR as (R1 & R2 & R3 & R4 & R5).
    pose proof OBJS as ((OP1 & OP2 & _) & (OV1 & OV2 & _) & (OS1 & OS2 & _) & (OE1 & OE2 & _) & _). unfold PMES.ENC_SIZE in OV2.
    pose proof (PmLayout.ly_errno L LAY) as LER. pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
    rewrite ILO, IHI in R2.
    assert (Hlen1 : Z.of_nat (length (PML.ps_stack ps ++ [KIND])) = slen + 1) by (rewrite length_app; cbn [length]; unfold slen; lia).
    split; [split; [|split]|].
    + rewrite xi_vis. split.
      * intros a Ha. rewrite <- (HS a Ha), <- (HLOW a (foot_low a Ha)). apply (L5C.hpres_kept _ _ _ _ _ _ _ a HP).
        pose proof (foot_low a Ha) as Fa.
        split; [lia|]. split; [|split].
        -- right. right. rewrite ILO, IHI. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. split; [lia|]. intros X. pose proof (PmLayout.ly_static L LAY a X). lia.
        -- unfold in_errno. rewrite LER. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. lia.
        -- intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha.
           destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH in *; lia.
      * exists b', cap'. split; [exact HdenE2|]. split.
        { apply (L5C.bytes_at_agree RSEGS M' M2 b' (PML.ps_stack ps ++ [KIND])); [| lia | rewrite Hlen1; lia |].
          - intros q Hq. rewrite Hlen1 in Hq. apply (L5C.hpres_kept _ _ _ _ _ _ _ q HP).
            split; [lia|]. split; [|split].
            + left. exists (b', cap'). split; [rewrite HdenE'; apply in_or_app; left; right; left; reflexivity | cbn [fst snd]; lia].
            + unfold in_errno. rewrite LER. lia.
            + intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw.
              destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH, PMES.ENC_SIZE in *; lia.
          - apply (kit SPT.bytes_below M1 M' b' cap' _ HLOW ltac:(lia) R5 ltac:(rewrite Hlen1; lia) Hby). }
        split; [exact Hcin|]. split; [exact Hcap | exact HBR].
    + exact (conj HEI2 HLT2).
    + unfold GF. rewrite Nat.eqb_refl. split; [exact Hes | exists pay; split; [exact Hpay | exact Hlen]].
    + unfold CredV, scap_of. rewrite BLS_vis, HdenE2. cbn [nth snd].
      unfold scap_of in HEC'. rewrite Hden in HEC'. cbn [nth snd] in HEC'. destruct HEC' as (EC1 & EC2 & EC3 & EC4).
      pose proof (KENC0 g') as K0. rewrite PMX.kenc_eq in K0. pose proof (EK.benc_nonneg L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) g') as K1.
      assert (BDc : bcap <= 2 ^ 27) by (unfold bcap; lia).
      assert (SK : 0 <= PPS.stk_kx L cap') by (unfold PPS.stk_kx; apply Z.mul_nonneg_nonneg; [apply Z.log2_nonneg | exact (PmLayout.ly_kpm L LAY)]).
      assert (SB : 0 <= PPS.stk_bx L cap').
      { unfold PPS.stk_bx. pose proof (Z.log2_nonneg (1056 / cap')) as Q1. pose proof (PmLayout.ly_bov L LAY) as Q2.
        assert (Q3 : cap' <= 1056) by (cbn [In] in Hcin; lia). clear - Q1 Q2 Q3. nia. }
      clear - EC1 EC2 EC3 EC4 K0 K1 BDc SK SB Hkx Hbxu0.
      unfold PPS.bufcred. repeat split; lia.
Qed.

