Section Final.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PML.fp_ok fx -> PML.fp_ok fx'.
Hypothesis VECPUSH_OK : PMS.vec_push_spec L HI.
Hypothesis SETEC_OK : PMS.set_ec_spec L.
Hypothesis VBARR : PMES.visit_begin_array_specU L HI PMES.WD_SCR_X.

(* [comment removed for export] *)
Theorem begin_array_okw : PMW.begin_array_specwU L HI PML.STRTOD_SCR_V PMES.WD_SCR_X PMR.the_rm.
Proof.
  unfold PMW.begin_array_specwU, PMW.begin_container_specwU, PMW.ptransxwU, PMW.ptrans_gxwU, PMW.ptrans_gbxwU.
  intros LBo cr sp r P V E S2 B kx bx g ps eg w x c. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp (Hentry & ((Ha0 & Ha1 & Ha2) & Hmore & Hncc & Hnstr) & HPA & HWF & HWIN & HBB & HVIS & HEC & HLS & HG & HINV & HLIT & HSYNC & Hkx & Hbx & HPC & OBJS & HWBY & HRM & HROOM) Hcont.
  pose proof (SPT.pa_def _ _ _ HPA) as HdP.
  destruct (PB2.cell_exists M (P + 160) 8 ltac:(lia)) as (line0 & Rl & Hl); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  destruct (PB2.cell_exists M (P + 168) 8 ltac:(lia)) as (pos0 & Rp & Hp); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  eapply main.
  all: first [exact HIok | exact LAY | exact FPM | exact VECPUSH_OK | exact SETEC_OK | exact VBARR | exact HH | exact Hmo | exact HKnil | exact Hfp | exact Hentry
             | exact Ha0 | exact Ha1 | exact Ha2 | exact Hmore | exact Hncc | exact Hnstr | exact HPA | exact HWF | exact HWIN | exact HBB | exact HVIS | exact HEC
             | exact HLS | exact HG | exact HINV | exact HLIT | exact HSYNC | exact Hkx | exact HPC | exact eq_refl | exact Hbx | exact OBJS | exact HWBY | exact HRM
             | exact HROOM | exact Hcont | exact Hl | exact Hp | exact (conj Rl Rp)].
Qed.

End Final.
